    const wrongs = [Math.round(N / scale) * scale, good + scale, good - scale].filter((w, i, a) => w > 0 && w !== good && !easy(w) && a.indexOf(w) === i).map(w => ({text:commas(w), mis:'compatibleNumber'}));
    if (wrongs.length < 2) continue;
