const tryGen = f => { for (let t = 0; t < 300; t++) { const p = f(); if (p) return p; } throw new Error('no problem'); };
/* an expression in x (and y) as text plus a function, so options can be checked for equivalence */
const EX = (text, f) => ({text, f});
