    if (kind === 'add high') { val = s[n - 1] + rand(10, 25); next = [...data, val]; } else if (kind === 'add low') { val = Math.max(0, s[0] - rand(5, 8)); next = [...data, val]; }
    else if (kind === 'remove high') { val = s[n - 1]; next = s.slice(0, n - 1); } else { val = s[0]; next = s.slice(1); }
