function show(id){
  if (id !== 'room' && roomDrag) finishRoomDrag();
  if (id === 'arcade' && !arcadePolicy().enabled) { toast('Your teacher has not opened the Arcade.'); id = 'home'; }
  SCREENS.forEach(s => $('#scr-'+s).hidden = (s !== id));
  Music.setTempo(id === 'sprint' ? SPRINT_RATE : 1);
  updateHeader();
  if (id === 'home') { renderHome(); if (Backend.me) void Backend.refreshSettings().then(() => { if (!$('#scr-home').hidden) renderSentBack(); }); }
  if (id === 'room') renderPetRoom();
  if (id === 'artstudio') renderArtStudio();
  if (id === 'cafe') renderShopFloor(currentShop);
  if (id === 'book') { const b = BUILDINGS.find(x => x.id === bookUnit), hood = currentHood(), list = viewSubject ? buildingsInClass(hood, viewSubject) : buildingsIn(hood); renderBook(b && b.hood === hood && (!viewSubject || b.subject === viewSubject) ? bookUnit : list[0].id); }
  if (id === 'library') { renderEnglishLibrary(); if (Backend.me) void Backend.refreshSettings().then(() => { if (!$('#scr-library').hidden && $('#libraryWrap .ela-layout')) renderEnglishLibrary(); }); }
  if (id === 'arcade') renderArcade();
  if (id === 'vocab') renderVocab(); else { if (vocabRun) { stopVocabTimer(); vocabRun = null; } if (puzzleRun || checkRun) stopPuzzleRun(); }
  syncRoom(id);
  window.scrollTo(0,0);
  if (brainRun && (id === 'join' || id === 'name' || id === 'loading')) closeBrainStretch(false);   // signed out: the stretch waits in the save
  if (moveRun && (id === 'join' || id === 'name' || id === 'loading')) closeMoveBreak();            // the same for a stand-and-stretch break
  bibleCheck();
  brainCheck();
  moveCheck();
  themeCheck();
}
/* Themed room behind building screens (src/game/rooms.js). Summary keeps the room it came from. */
function syncRoom(id){
  if (id === 'summary') return;
  if (id === 'join' || id === 'name') { applyRoom('welcome', null, [], WELCOME_PETS); return; }   // pets stroll past the sign-in screens
  const building = id === 'cafe' ? currentShop : id === 'shift' ? (shift?.shop || currentShop)
    : id === 'library' ? (englishRun?.shop || englishCourse(activeEnglishCourse).building) : null;   // a math Think it through set stays in its shop
  const b = building && BUILDINGS.find(x => x.id === building);
  if (!b) { applyRoom(null); return; }
  // pets unlocked in this building live in its room; museums, libraries, and the nature center get the student's pets as visitors
  const unitPets = REWARDS.filter(r => r.unit === b.id && r.kind === 'pet' && owns(r));
  const pets = (unitPets.length ? unitPets : b.subject === 'math' ? [] : ownedPets().slice(0, 4)).map(r => ({emoji:r.emoji, name:r.name.split(' ')[0]}));
  applyRoom(b.id, b.subject, REWARDS.filter(r => r.unit === b.id && r.kind === 'decor' && owns(r)).map(r => r.emoji), pets);
}
