  assignedExtras().forEach(x => { if (extraFullyDone(x)) fresh.push([`extra:${x.id}`, extraLabel(x), '']); });
  goalRows.forEach(([id, name, goal]) => { if (Math.floor((today[id] || 0) / 60) >= goal) fresh.push([`goal:${id}`, `${name}: ${goal} min`, id]); });
