    const pick = attr => wrap.querySelectorAll(`[${attr}]`).forEach(x => { x.classList.toggle('mint', x === b); x.setAttribute('aria-pressed', String(x === b)); });
    if (b.dataset.scribeWedge) { wedge = b.dataset.scribeWedge; pick('data-scribe-wedge'); }
