      b.disabled = true; const title = sys.id === 'oracle' ? 'My oracle bone question' : `${scribeRun.name || S.name || 'My name'} in ${sys.id === 'cuneiform' ? 'cuneiform' : sys.id === 'hieroglyphs' ? 'hieroglyphs' : 'Greek letters'}`;
