  extraSecs(id); S.extrasLog.challenge = {...(S.extrasLog.challenge || {}), [id]:right};
  const best = S.challengeBest?.[id] || 0; S.challengeBest = {...(S.challengeBest || {}), [id]:Math.max(best, right)};
  const log = S.challengeLog?.[id] || [];
