  const hood = e.target.closest('[data-hood]'); if (hood) { viewHood = hood.dataset.hood; viewSubject = null; sfx('tick'); renderHome(); const t = $(`#town [data-hood="${viewHood}"]`); if (t) t.focus(); return; }
