const isHistoryCourse = id => id === 'history' || id === 'history2' || id === 'history3' || id === 'history4' || id === 'history5' || id === 'history6' || id === 'history7' || id === 'history8' || id === 'history9';
const HISTORY_BUILDING_COURSE = {histOrigins:'history',histEarly:'history2',histAgrarian:'history3',histEmpires:'history4',histWebs:'history5',bioChem:'bio1',bioCells:'bio2',bioEnergy:'bio3',bioDivide:'bio4',histGlobal1:'history6',histLong19:'history7',histConflict:'history8',histGlobal2:'history9'};
const isScienceCourse = id => /^bio\d+$/.test(id);
const isProjectCourse = id => isHistoryCourse(id) || isScienceCourse(id) || id === 'prepositions';
const progressStore = id => id === 'math' ? S.mathThink : isHistoryCourse(id) ? S.historyProgress : isScienceCourse(id) ? S.scienceProgress : S.elaProgress;
const projectStore = key => String(key).startsWith('bio') ? S.scienceProjects : S.historyProjects;   // English projects live with History's
const projectKeys = id => [id, `${id}lab`, `${id}lab2`, `${id}lab3`].filter(key => HISTORY_PROJECTS[key]);
/* History and Biology role play: in History the student is a historical figure (or an everyday person of the time) answering
   visitors' questions; in Biology the student is a tour guide at the Nature Center. One card per skill (docs: tone change). */
/* 🖼️ the role's scene (docs/ROLE-SCENES.md): a real picture with a caption, a world map pin for where, and a timeline
   for when. Open on the first question of a practice; after that it folds up under "See the scene". A picture that
   can't load (offline, blocked) just isn't shown; the map and timeline still are. */
function roleSceneHTML(skillId, courseId, open){
  const x = ROLE_SCENES[skillId]; if (!x) return '';
  const pic = x.img ? `<figure class="scene-pic"><img src="${commonsThumb(x.img, 500)}" alt="${esc(x.cap)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.closest('figure').remove()"><figcaption>${esc(x.cap)}<small>${esc(x.credit || 'Wikimedia Commons')}</small></figcaption></figure>` : '';
  const [lat, lon] = x.at || [], pin = Number.isFinite(lat) && Number.isFinite(lon) ? `<div class="scene-map" role="img" aria-label="Map: ${esc(x.place || '')}"><img src="${commonsThumb(WORLD_MAP, 500)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()"><span class="scene-pin" style="left:${((lon + 180) / 360 * 100).toFixed(1)}%;top:${((90 - lat) / 180 * 100).toFixed(1)}%">📍</span><b class="scene-place">${esc(x.place || '')}</b></div>` : '';
  const era = COURSE_ERAS[courseId], y = Number(x.year);
  const line = era && Number.isFinite(y) ? (() => { const [a, b] = era, at = Math.max(0, Math.min(100, (y - a) / (b - a) * 100));
    return `<div class="scene-when"><div class="scene-bar"><span class="scene-dot" style="left:${at.toFixed(1)}%"></span></div><div class="scene-ends"><span>${yearText(a)}</span><b>${esc(x.when || yearText(y))}</b><span>${yearText(b)}</span></div></div>`; })() : '';
  const body = `${pic}<div class="scene-where">${pin}${line}</div>`;
  return open ? `<section class="role-scene">${body}</section>` : `<details class="role-scene"><summary>🖼️ See the scene again</summary>${body}</details>`;
}
