    orders:Object.entries(d.counts).map(([key, c]) => { const [, shop, station] = key.split(':'); return {key, label:stationLabel(shop, station), n:c.n, ok:c.ok}; }),
    events:d.events.map(e => ({...e, text:e.text || eventText(e)})),
